<script setup lang="ts">
import type { ECOption } from '@/hooks/common/echarts';

interface Suggestion { id:string;name:string;crop:string;type:string;typeLabel:string }
interface GraphNode { id:string;label:string;type:string;imageUrl?:string;properties:Record<string,any> }
interface GraphEdge { id:string;source:string;target:string;label:string;type:string }
interface GraphResult { nodes:GraphNode[];edges:GraphEdge[];degraded:boolean;message:string;rootId:string;availableRelationTypes:string[];relationCounts:Record<string,number> }
interface Overview { crop:string;entityCounts:Record<string,number>;relationCoverage:Record<string,number>;imageCoveredEntities:number;verifiedImages:number;featuredEntities:Suggestion[] }
interface ImageItem { id:string;url:string;license:string;sourcePage:string }
interface EntityDetail { id:string;name:string;crop:string;category:string;categoryLabel:string;summary:string;symptoms:string;pathogen:string;occurrenceFactors:string;controlOptions:{name:string;type:string}[];affectedParts:string[];images:ImageItem[] }

const route=useRoute();
const router=useRouter();
const crop=ref(String(route.query.crop||'番茄'));
const mode=ref<'overview'|'entity'|'path'>((route.query.mode as any)||'overview');
const overview=ref<Overview|null>(null);const graph=ref<GraphResult>({nodes:[],edges:[],degraded:false,message:'',rootId:'',availableRelationTypes:[],relationCounts:{}});
const root=ref<Suggestion|null>(null);const selected=ref<GraphNode|null>(null);const selectedDetail=ref<EntityDetail|null>(null);const relatedEntities=ref<Suggestion[]>([]);
const query=ref('');const suggestions=ref<Suggestion[]>([]);const loading=ref(false);const history=ref<Suggestion[]>([]);
const relationTypes=ref<string[]>(['HAS_SYMPTOM','CAUSED_BY','HAS_CONTROL_MEASURE','AFFECTS_PART','PROMOTED_BY']);
const pathSource=ref<Suggestion|null>(null);const pathTarget=ref<Suggestion|null>(null);const pathSourceQuery=ref('');const pathTargetQuery=ref('');const pathSourceSuggestions=ref<Suggestion[]>([]);const pathTargetSuggestions=ref<Suggestion[]>([]);
const themeStore=useThemeStore();const serviceBase=String(import.meta.env.VITE_SERVICE_BASE_URL||'').replace(/\/$/,'');
function mediaUrl(url?:string){return url?.startsWith('/api/v1')?`${serviceBase}${url.slice(7)}`:url}

const typeLabels:Record<string,string>={Crop:'作物',Disease:'病害',Pest:'虫害',Symptom:'症状',Pathogen:'病原',ControlMeasure:'防治措施',PlantPart:'危害部位',EnvironmentFactor:'环境条件',EnvironmentThreshold:'环境阈值',GrowthStage:'生育期',ImageCase:'图片案例'};
const relationLabels:Record<string,string>={HAS_DISEASE:'病害',HAS_PEST:'虫害',HAS_SYMPTOM:'症状',CAUSED_BY:'病原',HAS_CONTROL_MEASURE:'防治',AFFECTS_PART:'危害部位',PROMOTED_BY:'环境',HAS_IMAGE:'图片'};
const colors:Record<string,string>={Crop:'#2f7048',Disease:'#b4473d',Pest:'#a86435',Symptom:'#c28a2d',Pathogen:'#6d5e91',ControlMeasure:'#36717a',PlantPart:'#68786d',EnvironmentFactor:'#63804e',EnvironmentThreshold:'#8a7139',GrowthStage:'#9a7634',ImageCase:'#527a8d'};
const selectableRelations=['HAS_SYMPTOM','CAUSED_BY','HAS_CONTROL_MEASURE','AFFECTS_PART','PROMOTED_BY','HAS_IMAGE'];

const {domRef,updateOptions,getDataURL}=useEcharts(()=>baseOptions(),{onRender(chart){chart.on('click',params=>{if(params.dataType!=='node')return;const node=graph.value.nodes.find(item=>item.id===String((params.data as any).id));if(node)selectNode(node)})}});
function baseOptions():ECOption{return {tooltip:{formatter:(params:any)=>params.dataType==='edge'?(params.data.value||'关系'):`${params.data.name}<br/>${params.data.typeLabel}`},series:[{type:'graph',layout:'force',roam:true,draggable:true,force:{repulsion:420,gravity:.055,edgeLength:[105,185]},label:{show:true,position:'right',color:themeStore.darkMode?'#dce7df':'#34423a',fontSize:12},lineStyle:{color:themeStore.darkMode?'#53665a':'#a9b7ad',width:1.3,curveness:.08},emphasis:{focus:'adjacency',lineStyle:{width:3}},data:[],links:[]}]} as ECOption}
function graphOptions():ECOption{const options=baseOptions() as any;options.series[0].data=graph.value.nodes.map(node=>({id:node.id,name:node.label,typeLabel:typeLabels[node.type]||node.type,symbol:node.type==='ImageCase'&&node.imageUrl?`image://${mediaUrl(node.imageUrl)}`:'circle',symbolSize:node.id===root.value?.id?62:node.type==='Disease'||node.type==='Pest'?46:34,itemStyle:{color:colors[node.type]||'#69766e',borderColor:node.id===selected.value?.id?'#e6b33b':'transparent',borderWidth:3}}));options.series[0].links=graph.value.edges.map(edge=>({source:edge.source,target:edge.target,value:edge.label||relationLabels[edge.type]||edge.type}));return options}

async function loadOverview(){loading.value=true;const {data}=await request<Overview>({url:'/graph/overview',params:{crop:crop.value}});overview.value=data||null;loading.value=false}
async function findSuggestions(target:'root'|'source'|'target'){
  const value=target==='root'?query.value:target==='source'?pathSourceQuery.value:pathTargetQuery.value;if(!value.trim())return;
  const {data}=await request<Suggestion[]>({url:'/graph/suggestions',params:{query:value.trim(),crop:crop.value,limit:16}});
  if(target==='root')suggestions.value=data||[];else if(target==='source')pathSourceSuggestions.value=data||[];else pathTargetSuggestions.value=data||[];
}
async function chooseRoot(item:Suggestion,pushHistory=true){if(pushHistory&&root.value&&root.value.id!==item.id)history.value.push(root.value);root.value=item;query.value=item.name;suggestions.value=[];mode.value='entity';relationTypes.value=['HAS_SYMPTOM','CAUSED_BY','HAS_CONTROL_MEASURE','AFFECTS_PART','PROMOTED_BY'];await explore()}
async function explore(){if(!root.value)return;loading.value=true;const {data,error}=await request<GraphResult>({url:'/graph/explore',params:{rootId:root.value.id,relationTypes:relationTypes.value.join(',')}});loading.value=false;if(error||!data)return;graph.value=data;await selectNode(data.nodes.find(item=>item.id===root.value?.id)||data.nodes[0]);await updateOptions(()=>graphOptions())}
async function selectNode(node?:GraphNode){if(!node)return;selected.value=node;selectedDetail.value=null;relatedEntities.value=[];if(node.type==='Disease'||node.type==='Pest'){const {data}=await request<EntityDetail>({url:`/agriculture/entities/${node.id}`});selectedDetail.value=data||null}else if(['Symptom','Pathogen','EnvironmentFactor','PlantPart','ControlMeasure'].includes(node.type)){const {data}=await request<Suggestion[]>({url:'/graph/related-entities',params:{nodeId:node.id,crop:crop.value,limit:10}});relatedEntities.value=data||[]}await updateOptions(()=>graphOptions())}
async function centerSelected(){if(!selected.value||!['Disease','Pest'].includes(selected.value.type))return;await chooseRoot({id:selected.value.id,name:selected.value.label,crop:crop.value,type:selected.value.type,typeLabel:typeLabels[selected.value.type]||selected.value.type})}
function openSelectedDetail(){if(selected.value)router.push(`/knowledge-base/${selected.value.id}`)}
async function goBack(){const previous=history.value.pop();if(previous)await chooseRoot(previous,false)}
async function runPath(){if(!pathSource.value||!pathTarget.value){window.$message?.warning?.('请选择两个准确实体');return}loading.value=true;const {data}=await request<GraphResult>({url:'/graph/path',params:{sourceId:pathSource.value.id,targetId:pathTarget.value.id,maxDepth:4}});loading.value=false;graph.value=data||{nodes:[],edges:[],degraded:false,message:'未找到关系路径',rootId:'',availableRelationTypes:[],relationCounts:{}};root.value=pathSource.value;selected.value=graph.value.nodes[0]||null;await updateOptions(()=>graphOptions())}
function choosePath(item:Suggestion,target:'source'|'target'){if(target==='source'){pathSource.value=item;pathSourceQuery.value=item.name;pathSourceSuggestions.value=[]}else{pathTarget.value=item;pathTargetQuery.value=item.name;pathTargetSuggestions.value=[]}}
function resetView(){updateOptions(()=>graphOptions())}
function exportPng(){const url=getDataURL();if(!url)return;const link=document.createElement('a');link.href=url;link.download=`agrigraph-${root.value?.name||'path'}.png`;link.click()}
function changeCrop(){overview.value=null;graph.value={nodes:[],edges:[],degraded:false,message:'',rootId:'',availableRelationTypes:[],relationCounts:{}};root.value=null;selected.value=null;selectedDetail.value=null;suggestions.value=[];query.value='';history.value=[];pathSource.value=null;pathTarget.value=null;loadOverview()}
function switchMode(value:'overview'|'entity'|'path'){mode.value=value;if(value==='overview')loadOverview()}
const selectedImage=computed(()=>selected.value?.imageUrl||selectedDetail.value?.images?.[0]?.url||'');
const mobileGroups=computed(()=>Object.entries(typeLabels).map(([type,label])=>({type,label,nodes:graph.value.nodes.filter(node=>node.type===type&&node.id!==root.value?.id)})).filter(group=>group.nodes.length));

onMounted(async()=>{const id=String(route.query.id||'');if(id){const {data}=await request<EntityDetail>({url:`/agriculture/entities/${id}`});if(data){crop.value=data.crop;await chooseRoot({id:data.id,name:data.name,crop:data.crop,type:data.category,typeLabel:data.categoryLabel},false);return}}await loadOverview()});
</script>

<template>
  <div class="graph-page">
    <header class="page-heading"><div><h1>农业知识图谱</h1><p>从作物概览进入单实体关系，或分析两个实体间的关联路径</p></div><NRadioGroup :value="mode" size="small" @update:value="switchMode"><NRadioButton value="overview">作物概览</NRadioButton><NRadioButton value="entity">单实体图谱</NRadioButton><NRadioButton value="path">路径分析</NRadioButton></NRadioGroup></header>
    <div class="mode-toolbar"><NSelect v-model:value="crop" :options="[{label:'番茄',value:'番茄'},{label:'水稻',value:'水稻'}]" @update:value="changeCrop" /><template v-if="mode==='entity'"><div class="entity-search"><NInput v-model:value="query" placeholder="输入准确的病害或虫害名称" @keyup.enter="findSuggestions('root')"><template #prefix><icon-solar:magnifer-linear /></template></NInput><div v-if="suggestions.length" class="suggestion-menu"><button v-for="item in suggestions" :key="item.id" type="button" @click="chooseRoot(item)"><span><b>{{ item.name }}</b><small>{{ item.crop||crop }} · {{ item.typeLabel }}</small></span><icon-solar:alt-arrow-right-linear /></button></div></div><NButton type="primary" @click="findSuggestions('root')">查找实体</NButton></template><template v-else-if="mode==='path'"><div class="entity-search"><NInput v-model:value="pathSourceQuery" placeholder="起点实体" @keyup.enter="findSuggestions('source')" /><div v-if="pathSourceSuggestions.length" class="suggestion-menu"><button v-for="item in pathSourceSuggestions" :key="item.id" type="button" @click="choosePath(item,'source')"><span><b>{{ item.name }}</b><small>{{ item.typeLabel }}</small></span></button></div></div><span class="path-arrow"><icon-solar:arrow-right-linear /></span><div class="entity-search"><NInput v-model:value="pathTargetQuery" placeholder="终点实体" @keyup.enter="findSuggestions('target')" /><div v-if="pathTargetSuggestions.length" class="suggestion-menu"><button v-for="item in pathTargetSuggestions" :key="item.id" type="button" @click="choosePath(item,'target')"><span><b>{{ item.name }}</b><small>{{ item.typeLabel }}</small></span></button></div></div><NButton @click="findSuggestions(pathSource?'target':'source')">查找</NButton><NButton type="primary" @click="runPath">分析路径</NButton></template></div>

    <template v-if="mode==='overview'">
      <NSpin :show="loading"><div v-if="overview" class="overview-panel"><section class="overview-stats"><div><span>病害</span><b>{{ overview.entityCounts.Disease||0 }}</b></div><div><span>虫害</span><b>{{ overview.entityCounts.Pest||0 }}</b></div><div><span>有核验图片的条目</span><b>{{ overview.imageCoveredEntities }}</b></div><div><span>核验图片关系</span><b>{{ overview.verifiedImages }}</b></div></section><section class="coverage-section"><header><h2>知识关系覆盖</h2><span>统计具备对应结构化关系的病虫害条目</span></header><div><span v-for="(count,type) in overview.relationCoverage" :key="type"><b>{{ relationLabels[type]||type }}</b><em>{{ count }} 个条目</em></span></div></section><section class="featured-section"><header><h2>高关联实体</h2><span>选择后进入单实体关系图</span></header><div><button v-for="item in overview.featuredEntities" :key="item.id" type="button" @click="chooseRoot(item,false)"><i :style="{background:colors[item.type]}" /><span><b>{{ item.name }}</b><small>{{ item.typeLabel }}</small></span><icon-solar:alt-arrow-right-linear /></button></div></section></div></NSpin>
    </template>

    <template v-else>
      <div v-if="mode==='entity'" class="relation-bar"><span>关系范围</span><NCheckboxGroup v-model:value="relationTypes" @update:value="explore"><NCheckbox v-for="type in selectableRelations" :key="type" :value="type" :disabled="!root"><span>{{ relationLabels[type] }}</span><small v-if="graph.relationCounts[type]">{{ graph.relationCounts[type] }}</small></NCheckbox></NCheckboxGroup><div class="graph-actions"><NButton quaternary circle title="返回上一个中心" :disabled="!history.length" @click="goBack"><template #icon><icon-solar:undo-left-linear /></template></NButton><NButton quaternary circle title="适应画布" @click="resetView"><template #icon><icon-solar:maximize-square-minimalistic-linear /></template></NButton><NButton quaternary circle title="导出PNG" @click="exportPng"><template #icon><icon-solar:download-minimalistic-linear /></template></NButton></div></div>
      <div class="graph-workspace"><main class="canvas-panel"><div ref="domRef" class="graph-canvas" /><NEmpty v-if="!loading&&!graph.nodes.length" :description="graph.message||'查找并选择准确实体'" class="canvas-empty" /></main><main class="mobile-relations"><section v-for="group in mobileGroups" :key="group.type"><h3>{{ group.label }} · {{ group.nodes.length }}</h3><button v-for="node in group.nodes" :key="node.id" type="button" @click="selectNode(node)">{{ node.label }}<icon-solar:alt-arrow-right-linear /></button></section></main><aside class="detail-panel"><template v-if="selected"><div class="type-line"><i :style="{background:colors[selected.type]||'#69766e'}" />{{ typeLabels[selected.type]||selected.type }}</div><h2>{{ selected.label }}</h2><img v-if="selectedImage" class="node-image" :src="mediaUrl(selectedImage)" :alt="selected.label" /><template v-if="selectedDetail"><p>{{ selectedDetail.summary }}</p><div class="detail-buttons"><NButton v-if="selected.id!==root?.id" type="primary" size="small" @click="centerSelected">以此为中心</NButton><NButton size="small" @click="openSelectedDetail">完整详情</NButton></div><dl><dt>危害部位</dt><dd>{{ selectedDetail.affectedParts.join('、')||'待补充' }}</dd><dt>典型症状</dt><dd>{{ selectedDetail.symptoms||'待补充' }}</dd><dt>病原信息</dt><dd>{{ selectedDetail.pathogen||'待补充' }}</dd><dt>发生条件</dt><dd>{{ selectedDetail.occurrenceFactors||'待补充' }}</dd><dt>防治选项</dt><dd>{{ selectedDetail.controlOptions?.map(option => option.name).join('、')||'待补充' }}</dd></dl></template><template v-else><p>{{ selected.properties.summary||`${selected.label}的农业知识图谱节点。` }}</p><div v-if="relatedEntities.length" class="related-entities"><b>关联病虫害</b><button v-for="item in relatedEntities" :key="item.id" type="button" @click="chooseRoot(item)">{{ item.name }}</button></div><dl><dt>实体类别</dt><dd>{{ typeLabels[selected.type]||selected.type }}</dd><template v-if="selected.type==='ImageCase'"><dt>图片许可</dt><dd>{{ selected.properties.license||'待核验' }}</dd><dt>图片来源</dt><dd>{{ selected.properties.sourcePage||selected.properties.sourceDatasetId||'公开数据集' }}</dd></template></dl></template></template><NEmpty v-else description="选择节点查看农业信息" /></aside></div>
    </template>
  </div>
</template>

<style scoped lang="scss">
.graph-page{min-height:calc(100vh - 112px);display:flex;flex-direction:column;color:var(--agri-text)}.page-heading{display:flex;align-items:flex-end;justify-content:space-between;padding:4px 2px 14px}.page-heading h1{margin:0;font-size:22px}.page-heading p{margin:4px 0 0;color:var(--agri-text-secondary)}.mode-toolbar{display:grid;grid-template-columns:120px minmax(260px,1fr) auto;gap:9px;padding:11px;border:1px solid var(--agri-border);background:var(--agri-surface)}.mode-toolbar:has(.path-arrow){grid-template-columns:110px minmax(180px,1fr) 22px minmax(180px,1fr) auto auto}.entity-search{position:relative}.suggestion-menu{position:absolute;top:39px;right:0;left:0;z-index:20;max-height:320px;overflow:auto;border:1px solid var(--agri-border);background:var(--agri-surface);box-shadow:0 10px 24px rgba(20,35,25,.18)}.suggestion-menu button{width:100%;display:flex;align-items:center;justify-content:space-between;padding:10px 12px;border:0;border-bottom:1px solid var(--agri-border);background:transparent;color:var(--agri-text);text-align:left;cursor:pointer}.suggestion-menu button:hover{background:var(--agri-surface-active)}.suggestion-menu span{display:flex;flex-direction:column}.suggestion-menu small{margin-top:3px;color:var(--agri-text-muted)}.path-arrow{display:grid;place-items:center;color:var(--agri-text-muted)}.overview-panel{border:1px solid var(--agri-border);border-top:0;background:var(--agri-surface)}.overview-stats{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--agri-border)}.overview-stats>div{padding:22px;border-right:1px solid var(--agri-border)}.overview-stats span{display:block;color:var(--agri-text-muted)}.overview-stats b{display:block;margin-top:8px;font-size:28px}.coverage-section,.featured-section{padding:24px}.coverage-section{border-bottom:1px solid var(--agri-border)}.coverage-section header,.featured-section header{display:flex;align-items:center;justify-content:space-between}.coverage-section h2,.featured-section h2{margin:0;font-size:17px}.coverage-section header span,.featured-section header span{color:var(--agri-text-muted)}.coverage-section>div{display:grid;grid-template-columns:repeat(5,1fr);margin-top:18px;border-top:1px solid var(--agri-border);border-left:1px solid var(--agri-border)}.coverage-section>div>span{padding:16px;border-right:1px solid var(--agri-border);border-bottom:1px solid var(--agri-border)}.coverage-section b,.coverage-section em{display:block}.coverage-section em{margin-top:6px;color:var(--agri-primary);font-style:normal}.featured-section>div{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin-top:18px;border-top:1px solid var(--agri-border);border-left:1px solid var(--agri-border)}.featured-section button{display:grid;grid-template-columns:10px 1fr auto;align-items:center;gap:10px;padding:15px;border:0;border-right:1px solid var(--agri-border);border-bottom:1px solid var(--agri-border);background:transparent;color:var(--agri-text);text-align:left;cursor:pointer}.featured-section button:hover{background:var(--agri-surface-active)}.featured-section i{width:9px;height:9px;border-radius:50%}.featured-section span{display:flex;flex-direction:column}.featured-section small{margin-top:3px;color:var(--agri-text-muted)}.relation-bar{display:flex;align-items:center;gap:14px;padding:8px 12px;border:1px solid var(--agri-border);border-top:0;background:var(--agri-surface-soft)}.relation-bar>span{color:var(--agri-text-muted);font-size:12px}.relation-bar :deep(.n-checkbox-group){display:flex;flex:1;flex-wrap:wrap;gap:13px}.relation-bar small{margin-left:3px;color:var(--agri-primary)}.graph-actions{display:flex}.graph-workspace{min-height:620px;flex:1;display:grid;grid-template-columns:minmax(0,1fr) 360px;border:1px solid var(--agri-border);border-top:0;background:var(--agri-surface)}.canvas-panel{position:relative;min-width:0;background-color:var(--agri-surface-soft);background-image:radial-gradient(var(--agri-canvas-dot) 1px,transparent 1px);background-size:18px 18px}.graph-canvas{width:100%;height:100%;min-height:620px}.canvas-empty{position:absolute;inset:0;display:grid;place-content:center}.detail-panel{max-height:700px;overflow:auto;padding:20px;border-left:1px solid var(--agri-border)}.type-line{display:flex;align-items:center;gap:7px;color:var(--agri-primary);font-size:12px}.type-line i{width:9px;height:9px;border-radius:50%}.detail-panel h2{margin:6px 0 12px;font-size:21px}.detail-panel>p,.detail-panel p{color:var(--agri-text-secondary);line-height:1.7}.node-image{width:100%;max-height:220px;object-fit:cover;margin-bottom:14px;border:1px solid var(--agri-border)}.detail-buttons{display:flex;gap:7px}.detail-panel dl{margin:14px 0;border-top:1px solid var(--agri-border)}.detail-panel dt{margin-top:13px;color:var(--agri-text-muted);font-size:12px}.detail-panel dd{max-height:140px;overflow:auto;margin:4px 0 0;line-height:1.65;white-space:pre-line}.related-entities{display:flex;flex-wrap:wrap;gap:6px}.related-entities b{width:100%}.related-entities button{padding:5px 8px;border:1px solid var(--agri-border);background:transparent;color:var(--agri-primary);cursor:pointer}.mobile-relations{display:none}@media(max-width:900px){.mode-toolbar:has(.path-arrow){grid-template-columns:100px 1fr 20px 1fr}.mode-toolbar:has(.path-arrow)>.n-button{display:none}.overview-stats{grid-template-columns:1fr 1fr}.coverage-section>div{grid-template-columns:1fr 1fr}.featured-section>div{grid-template-columns:1fr 1fr}.graph-workspace{grid-template-columns:minmax(0,1fr) 290px}}@media(max-width:700px){.page-heading{align-items:flex-start;flex-direction:column;gap:12px}.page-heading p{display:none}.mode-toolbar,.mode-toolbar:has(.path-arrow){grid-template-columns:100px 1fr}.mode-toolbar>.n-button,.path-arrow{display:none}.relation-bar{align-items:flex-start;overflow-x:auto}.relation-bar>span,.graph-actions{display:none}.relation-bar :deep(.n-checkbox-group){min-width:580px}.overview-stats,.featured-section>div{grid-template-columns:1fr 1fr}.coverage-section>div{grid-template-columns:1fr}.graph-workspace{display:block}.canvas-panel{display:none}.mobile-relations{display:block}.mobile-relations section{border-bottom:1px solid var(--agri-border)}.mobile-relations h3{margin:0;padding:12px 14px;background:var(--agri-surface-soft);font-size:14px}.mobile-relations button{width:100%;display:flex;justify-content:space-between;padding:12px 14px;border:0;border-bottom:1px solid var(--agri-border);background:transparent;color:var(--agri-text);text-align:left}.detail-panel{max-height:none;border-left:0;border-top:1px solid var(--agri-border)}}
</style>
